TR["lo"] = ("ສະຖານທີ່ທ່ອງທ່ຽວດ້ວຍຕົນເອງໃນດາລັດ: 29 ແຫ່ງ ເວລາເປີດ ແລະເສັ້ນທາງ | Van Phu",
 "ສະຖານທີ່ທ່ອງທ່ຽວດາລັດດ້ວຍຕົນເອງ",
 "ສະຖານທີ່ທ່ອງທ່ຽວດ້ວຍຕົນເອງ 29 ແຫ່ງໃນດາລັດ: ນໍ້າຕົກ ໄຮ່ຊາ ວັດ ຕະຫຼາດກາງຄືນ ແລະສວນດອກໄມ້ — ເວລາເປີດຈາກ Google Maps ລາຄາປີ້ໂດຍປະມານ ແລະເສັ້ນທາງ.",
 "29 ສະຖານທີ່ທີ່ນັກທ່ອງທ່ຽວມັກໃສ່ໃນແຜນເດີນທາງດາລັດ ເຊັ່ນ ນໍ້າຕົກ ເນີນຊາ ວັດ ສວນດອກໄມ້ ແລະຕະຫຼາດກາງຄືນ. ສ່ວນໃຫຍ່ຢູ່ໃນລັດສະໝີ 15 ກມ ຈາກທະເລສາບ Xuân Hương; ນໍ້າຕົກ Pongour, Samten Hills ແລະ ZooDoo ໄກກວ່າ ເໝາະກັບການໄປເປັນມື້ແຍກຕ່າງຫາກ.",
 "ສະຖານທີ່ (1–29)", "ເວລາທີ່ດີທີ່ສຸດ",
 [("ລະດູແລ້ງ (ປະມານພະຈິກ–ເມສາ)", "ຝົນໜ້ອຍ ເບິ່ງດອກໄມ້ງ່າຍ ແລະໄປໄກໄດ້"), ("ຕອນເຊົ້າ", "ເນີນຊາ Dreamy Hill ແລະ Langbiang ມັກມີເມກ ແລະໝອກສວຍກວ່າ"), ("ວັນເຮັດວຽກ", "ນັກທ່ອງທ່ຽວໜ້ອຍກວ່າວັນຫຍຸດສຸດອາທິດຫຼາຍ"), ("ສຸດອາທິດ ແລະ Tết", "Valley of Love, Fresh Garden ແລະ Langbiang ແອອັດ ອາດຕິດຂັດ")],
 "ຄວນຮູ້",
 ["ລາຄາໃນແຜນທີ່ເປັນລາຄາປະມານຈາກຄວາມເຫັນຂອງນັກທ່ອງທ່ຽວຫຼ້າສຸດ — ກວດຄືນທີ່ປະຕູກ່ອນໄປ.",
  "Madame De Dalat ປິດວັນອາທິດ; ໂບດ Domaine de Marie ປິດພັກທ່ຽງ 11:30–13:30.",
  "ຄວາມເຫັນລະບຸວ່ານໍ້າຕົກ Elephant ບາງເທື່ອປິດ ແລະ Tea Resort Prenn ມີສິ່ງອຳນວຍຄວາມສະດວກບໍ່ຄົບ; ຄວນສອບຖາມກ່ອນເດີນທາງໄກ.",
  "Samten Hills, ZooDoo ແລະ Pongour ຫ່າງຈາກໃຈກາງເມືອງ 25–35 ກມ — ແນະນຳມໍເຕີໄຊ 125cc ຫຼືສກູດເຕີໄຟຟ້າທີ່ແບັດເຕີຣີເຕັມ."],
 [("ນໍ້າຕົກ Datanla", "ຕອນເຊົ້າ", "ນໍ້າຕົກໃນປ່າສົນເທິງດ່ານ Prenn; ລົງດ້ວຍລາງເລື່ອນ alpine ຍາວ 2.4 ກມ ຫຼືຍ່າງລົງ."),
  ("Valley of Love", "ຕອນເຊົ້າ ຫຼື ແລງ", "ສວນສາທາລະນະໃຫຍ່ ມີສວນດອກໄມ້ ສະພານແກ້ວ ລາງເລື່ອນ ແລະລົດລູຈ. ຕາມຄວາມເຫັນ ປີ້ເຕັມປະມານ 250,000 ດົງ. ຄວນໃຊ້ເວລາຢ່າງໜ້ອຍ 3 ຊົ່ວໂມງ."),
  ("Samten Hills", "ຕອນເຊົ້າ", "ສັບປະລິເວນວັດພຸດທະສາສະໜາແບບທິເບດທີ່ Đơn Dương ມີລໍ້ອະທິຖານທອງແດງຂະໜາດໃຫຍ່; ປະມານ 27 ກມ ຈາກໃຈກາງເມືອງ."),
  ("Flower Plateau (Cao nguyên Hoa)", "ຕອນເຊົ້າ", "ເຂດນິເວດໃນເນີນ Tà Nung ມີເຮືອນໄມ້ໃນປ່າສົນ; ເສັ້ນທາງໂກຄາດລົງເນີນແມ່ນຈຸດດຶງດູດຫຼັກ."),
  ("Fresh Garden", "ຕອນເຊົ້າ", "ສວນດອກໄມ້ໃຫຍ່ທີ່ Vạn Thành ມີສວນສັດນ້ອຍ ບ່ອປາ ແລະຮ້ານກາເຟ; ປີ້ລວມເຄື່ອງດື່ມ."),
  ("ZooDoo", "ຕອນເຊົ້າ", "ສວນສັດໃນປ່າສົນທີ່ Lạc Dương ປະມານ 25 ກມ; ທົວມີໄກ້ດ໌ 1.5–2 ຊົ່ວໂມງ. ຄວນຈອງລ່ວງໜ້າ."),
  ("ພູ Langbiang", "ແຕ່ເຊົ້າ", "ຍອດພູປະມານ 2,167 ມ; ຂຶ້ນດ້ວຍລົດຈີບ ຫຼືລົດຮັບສົ່ງໄປເນີນ Radar ຫຼືຍ່າງຜ່ານປ່າ."),
  ("ເນີນ Robin ແລະກະເຊົ້າລອຍ", "ຕອນເຊົ້າ", "ກະເຊົ້າລອຍຍາວປະມານ 2 ກມ ໄປວັດ Trúc Lâm ປະມານ 10–15 ນາທີຕໍ່ເທື່ອ."),
  ("Madame De Dalat", "ຕອນເຊົ້າ", "ວິລລ່າເກົ່າຂອງ Trần Lệ Xuân ມີສວນ ແລະພິພິທະພັນ; ປິດວັນອາທິດ."),
  ("ປ່າສົນ Núi Voi", "ທັງມື້", "ປ່າສົນແດງທີ່ຫາຍາກ ມີຕົ້ນໄມ້ເກົ່າ ນໍ້າຕົກຊັ້ນ ພາຍກາຍັກ ແລະໂກຄາດ."),
  ("ທະເລສາບ Tuyền Lâm", "ແລງ", "ທະເລສາບໃຫຍ່ປະມານ 5 ກມ ຈາກໃຈກາງເມືອງ; ຂີ່ເຮືອຖີບ ແລະເບິ່ງຕາເວັນຕົກຈາກຝັ່ງ."),
  ("Delight Park Đà Lạt", "ຕອນແລງ", "ສວນສະໜຸກທີ່ມີສວນດອກໄມ້ ເຄື່ອງເຫຼັ້ນ ແລະການສະແດງແສງຕອນກາງຄືນ."),
  ("ອຸໂມງຮູບປັ້ນດິນໜຽວ", "ຕອນເຊົ້າ", "ທາງດິນໜຽວແດງທີ່ມີຮູບປັ້ນບອກປະຫວັດສາດ ແລະທິວທັດ; ເຂດ 'ບໍ່ມີທີ່ສິ້ນສຸດ' ໃກ້ທະເລສາບນິຍົມຖ່າຍຮູບ."),
  ("Fairytale Land", "ຕອນເຊົ້າ", "ສວນແບບນິທານ ມີເຮືອນກົມແບບ Hobbit ແລະຫ້ອງເກັບໄວນ໌ Vĩnh Tiến; ການຊິມໄວນ໌ເສຍເງິນເພີ່ມ."),
  ("Domaine de Marie (ໂບດສີບົວ)", "ຕອນເຊົ້າ", "ໂບດສີບົວເທິງເນີນ Mai Anh ມີສວນດອກໄມ້; ເຂົ້າຟຣີ. ຕອນມີພິທີມິສ ຢ່າຂັດທາງ."),
  ("ນໍ້າຕົກ Pongour", "ທັງມື້", "ນໍ້າຕົກເຈັດຊັ້ນເທິງຫີນທີ່ມີຂີ້ຝຸ່ນ ຫ່າງຈາກດາລັດປະມານ 50 ກມ; ລົດກອຟລົງປະມານ 15,000 ດົງຕໍ່ເທື່ອ."),
  ("ສວນກາເຟ Mê Linh", "ຕອນເຊົ້າ", "ໄຮ່ກາເຟພ້ອມທົວຂະບວນການແປຮູບ ແລະເບິ່ງແມວຊີວາທີ່ຜະລິດກາເຟ Weasel."),
  ("Tea Resort Prenn", "ຕອນເຊົ້າ", "ລີສອດຂ້າງນໍ້າຕົກ Prenn ມີກິດຈະກຳກາງແຈ້ງ; ຄວາມເຫັນດ້ານບໍລິການ ແລະສິ່ງອຳນວຍຄວາມສະດວກມີທັງດີ ແລະບໍ່ດີ."),
  ("ນໍ້າຕົກ Elephant (Thác Voi)", "ຕອນເຊົ້າ", "ນໍ້າຕົກໃຫຍ່ຂ້າງວັດ Linh An ປະມານ 17 ກມ ຈາກໃຈກາງເມືອງ; ບາງເທື່ອປິດ ແຕ່ເບິ່ງໄດ້ຈາກວັດ."),
  ("ວັດ Linh An", "ຕອນເຊົ້າ", "ວັດທີ່ມີຮູບປັ້ນ Lady Buddha ສູງ 71 ມ ແລະພຣະໄມທຣີຍະຂະໜາດໃຫຍ່; ເຂົ້າຟຣີ ແລະຈອດລົດຟຣີ."),
  ("ຕະຫຼາດກາງຄືນດາລັດ", "ແລງ", "ຕະຫຼາດກາງຄືນຕາມຖະໜົນ Nguyễn Thị Minh Khai ເປີດປະມານ 17:30 ຈົນດຶກ. ລອງເຈ້ຍເຂົ້າປີ້ງ ນົມຖົ່ວເຫຼືອງຮ້ອນ ແລະ bánh ướt lòng gà."),
  ("ໝູ່ບ້ານດອກໄມ້ Vạn Thành", "ຕອນເຊົ້າ", "ໝູ່ບ້ານດອກໄມ້ ແລະຜັກທີ່ Vạn Thành; ປີ້ປະມານ 100,000 ດົງຕໍ່ຄົນ ຕາມຄວາມເຫັນ."),
  ("ພິພິທະພັນຊາ Long Đỉnh", "ຕອນເຊົ້າ", "ພິພິທະພັນຊາທີ່ Trại Mát ມີທົວການຜະລິດ ແລະການຊິມ; ປີ້ປະມານ 100,000–150,000 ດົງຕາມແພັກເກດ."),
  ("ວັດ Linh Phước", "ຕອນເຊົ້າ", "ວັດທີ່ປະດັບດ້ວຍໂມເຊອິກຈາກເສດເຄື່ອງປັ້ນດິນເຜົາ ແລະແກ້ວ ມີສິມເຈັດຊັ້ນ; ເຂົ້າຟຣີ ປະມານ 6 ກມຈາກໃຈກາງເມືອງ."),
  ("Dalat Wonderland", "ຕອນເຊົ້າ", "ສວນສະໜຸກຂ້າງທະເລສາບ Tuyền Lâm ມີ ATV ລາງເລື່ອນ ແລະສວນສັດນ້ອຍ; ຕາມຄວາມເຫັນ ບາງເຄື່ອງເຫຼັ້ນປິດ ຫຼືເກົ່າ."),
  ("ໄຮ່ຊາ Cầu Đất", "ຕອນເຊົ້າ", "ເນີນຊາຂຽວປະມານ 15 ກມ ຈາກໃຈກາງເມືອງ ມີຊື່ສຽງດ້ານຕາເວັນຂຶ້ນ ແລະເມກ. Google Maps ລະບຸ 6:00–18:00."),
  ("Mongo Land", "ຕອນເຊົ້າ", "ສວນແບບມົງໂກລີ ມີເຕັນຢູວດ ແກະ ອູດ ແລະລາງເລື່ອນສາຍຮຸ້ງຍາວ; ປີ້ປະມານ 140,000 ດົງ ລວມເຄື່ອງດື່ມ 1 ແກ້ວ."),
  ("Dreamy Hill (Đồi Mộng Mơ)", "ຕອນເຊົ້າ", "ເນີນສວນປະມານ 12 ເຮັກຕາ ມີດອກໄມ້ ແລະພືດຕັດແຕ່ງ; ປີ້ຜູ້ໃຫຍ່ປະມານ 250,000 ດົງຕາມຄວາມເຫັນ. ດີທີ່ສຸດຈາກພະຈິກຫາມິຖຸນາ."),
  ("ຮ້ານກາເຟ Túi Mơ To", "ແລງ", "ຮ້ານກາເຟເທິງເນີນ ມີທາງດອກເດຊີ ແລະຊິງຊ້າ ເໝາະກັບການເບິ່ງຕາເວັນຕົກ; ສຸດອາທິດແອອັດ.")])

TR["my"] = ("ဒလတ်ရှိ ကိုယ်တိုင်သွားလည်နိုင်သော ခရီးသွားနေရာများ — ၂၉ နေရာ၊ ဖွင့်ချိန်နှင့် လမ်းညွှန် | Van Phu",
 "ဒလတ် ကိုယ်တိုင်သွားလည်နိုင်သော ခရီးသွားနေရာများ",
 "ဒလတ်ရှိ ကိုယ်တိုင်သွားလည်နိုင်သော နေရာ ၂၉ ခု — ရေတံခွန်၊ လက်ဖက်ခြံ၊ ဘုရားကျောင်း၊ ညဈေးနှင့် ပန်းခြံများ။ Google Maps ဖွင့်ချိန်၊ ခန့်မှန်းဈေးနှုန်းနှင့် လမ်းညွှန်။",
 "ခရီးသွားများ ဒလတ်ခရီးစဉ်တွင် မကြာခဏထည့်သွင်းသော နေရာ ၂၉ ခု — ရေတံခွန်၊ လက်ဖက်တောင်၊ ဘုရားကျောင်း၊ ပန်းခြံနှင့် ညဈေး။ အများစုသည် ဆူအန်ဟွန်ရေကန်မှ ၁၅ ကီလိုမီတာအတွင်း ရှိသည်။ ပွန်ဂူရ်ရေတံခွန်၊ Samten Hills နှင့် ZooDoo တို့မှာ ပိုဝေးသဖြင့် သီးခြားတစ်ရက်အတွက် သင့်တော်သည်။",
 "နေရာများ (၁–၂၉)", "သွားရောက်ရန် အကောင်းဆုံးအချိန်",
 [("ခြောက်သွေ့ရာသီ (နိုဝင်ဘာ–ဧပြီ ခန့်)", "မိုးနည်းပြီး ပန်းကြည့်ရန် လွယ်ကာ ဝေးဝေးသွားရန် ပိုအဆင်ပြေသည်"), ("နံနက်စော", "လက်ဖက်တောင်၊ Dreamy Hill နှင့် Langbiang တွင် တိမ်နှင့် မြူတွေ ပိုလှတတ်သည်"), ("တနင်္လာမှ သောကြာ", "စနေ၊ တနင်္ဂနွေထက် ခရီးသည် အတော်နည်းသည်"), ("စနေ၊ တနင်္ဂနွေနှင့် Tết", "Valley of Love၊ Fresh Garden နှင့် Langbiang တွင် လူများပြီး ယာဉ်ကြပ်နိုင်သည်")],
 "သိထားသင့်သည်များ",
 ["မြေပုံပေါ်ရှိ ဈေးနှုန်းများသည် မကြာသေးမီက သုံးသပ်ချက်များအပေါ် အခြေခံ၍ ခန့်မှန်းထားခြင်းဖြစ်သည် — သွားမီ ဝင်ပေါက်တွင် စစ်ဆေးပါ။",
  "Madame De Dalat သည် တနင်္ဂနွေနေ့တွင် ပိတ်သည်။ Domaine de Marie ဘုရားကျောင်းသည် နေ့လည် ၁၁:၃၀–၁၃:၃၀ တွင် ပိတ်သည်။",
  "သုံးသပ်ချက်များအရ Elephant ရေတံခွန်သည် တစ်ခါတစ်ရံ ပိတ်လေ့ရှိပြီး Tea Resort Prenn တွင် အဆောက်အအုံ မပြည့်စုံပါ — ဝေးဝေးသွားမီ မေးမြန်းပါ။",
  "Samten Hills၊ ZooDoo နှင့် ပွန်ဂူရ် သည် မြို့လယ်မှ ၂၅–၃၅ ကီလိုမီတာ ဝေးသည် — 125cc မော်တော်ဆိုင်ကယ် သို့မဟုတ် ဘက်ထရီအပြည့်ရှိသော လျှပ်စစ်စကူတာ သုံးပါ။"],
 [("Datanla ရေတံခွန်", "နံနက်", "Prenn တောင်ကြားရှိ လှိုင်းစိမ်းတောတွင် ရေတံခွန်; ၂.၄ ကီလိုမီတာ alpine coaster ဖြင့် ဆင်းနိုင်သလို လမ်းလျှောက်ဆင်းလည်းရသည်။"),
  ("Valley of Love", "နံနက် သို့မဟုတ် ညနေ", "ပန်းခြံ၊ ဖန်တံတား၊ ဆလိုက်နှင့် လွင့်ကားများပါသော ကျယ်ပြန့်သော ဥယျာဉ်။ သုံးသပ်ချက်အရ အပြည့်အစုံ လက်မှတ် ၂၅၀,၀၀၀ ဒေါင်ခန့်။ အနည်းဆုံး ၃ နာရီ ထားပါ။"),
  ("Samten Hills", "နံနက်", "Đơn Dương ရှိ ဗုဒ္ဓဘာသာ တိဗက်ဘုရားကျောင်းကွန်ပလက်စ်၊ ကြေးနီဆုတောင်းဘီး ကြီးမားသည်; မြို့လယ်မှ ၂၇ ကီလိုမီတာ ခန့်။"),
  ("Flower Plateau (Cao nguyên Hoa)", "နံနက်", "Tà Nung တောင်ကုန်းများရှိ ဂေဟစနစ်ဧရိယာ၊ စနှင့်တောအတွင်း သစ်သားအိမ်များ; တောင်ပေါ်မှ ဆင်းသော ဂိုကတ်လမ်းကြောင်းသည် အဓိက ဆွဲဆောင်မှုဖြစ်သည်။"),
  ("Fresh Garden", "နံနက်", "Vạn Thành ရှိ ကျယ်ပြန့်သော ပန်းခြံ၊ သားရဲ‌ဥယျာဉ်ငယ်၊ ငါးအိုင်နှင့် ကော်ဖီဆိုင်ပါသည်; လက်မှတ်တွင် ဖျော်ရည်ပါသည်။"),
  ("ZooDoo", "နံနက်", "Lạc Dương ရှိ စနှင့်တောအတွင်း သားရဲဥယျာဉ်၊ မြို့မှ ၂၅ ကီလိုမီတာခန့်; လမ်းညွှန်ခရီး ၁.၅–၂ နာရီ။ ကြိုတင်မှာယူပါ။"),
  ("Langbiang တောင်", "နံနက်စော", "အမြင့် ၂,၁၆၇ မီတာခန့် ထိပ်; Radar တောင်ကုန်းသို့ ဂျစ်ဖ်ကား သို့မဟုတ် ခရီးသည်တင်ကားဖြင့် တက်နိုင်သလို တောအတွင်း လမ်းလျှောက်လည်း တက်နိုင်သည်။"),
  ("Robin တောင်နှင့် ကေဘယ်ကား", "နံနက်", "Trúc Lâm ဇင်ကျောင်းသို့ ၂ ကီလိုမီတာခန့် ကေဘယ်ကား၊ တစ်ကြိမ် ၁၀–၁၅ မိနစ်ခန့်။"),
  ("Madame De Dalat", "နံနက်", "Trần Lệ Xuân ၏ ဟောင်းဗီလာ၊ ဥယျာဉ်နှင့် ပြတိုက်ပါသည်; တနင်္ဂနွေ ပိတ်သည်။"),
  ("Núi Voi စနှင့်တော", "တစ်နေ့လုံး", "ရှားပါးသော အနီရောင်စနှင့်တော၊ အသက်ကြီးသော သစ်ပင်များ၊ အဆင့်ဆင့် ရေတံခွန်၊ ကာယက်နှင့် ဂိုကတ်ပါသည်။"),
  ("Tuyền Lâm ရေကန်", "ညနေနောက်ပိုင်း", "မြို့လယ်မှ ၅ ကီလိုမီတာခန့် ကြီးမားသော ရေကန်; ခြေနင်းလှေစီးရန်နှင့် ကမ်းဘေးမှ နေဝင်ချိန်ကြည့်ရန်။"),
  ("Delight Park Đà Lạt", "ညနေ", "ပန်းခြံ၊ စက်ရုပ်အပန်းဖြေကွင်းနှင့် ညဘက် အလင်းပြကွက်ပါသော ဥယျာဉ်။"),
  ("ရွှံ့ရုပ်ပြတိုဂူ", "နံနက်", "အနီရောင်ရွှံ့ဖြင့် ပြုလုပ်ထားသော ရုပ်တုများ၊ မြို့၏သမိုင်းနှင့် ရှုခင်းကို ပြသသည်; ရေကန်ဘေးရှိ 'အဆုံးမရှိ' ဧရိယာသည် ဓာတ်ပုံရိုက်ရန် လူကြိုက်များသည်။"),
  ("Fairytale Land", "နံနက်", "ပုံပြင်ဆန်သော ဥယျာဉ်၊ Hobbit ပုံစံ စက်ဝိုင်းအိမ်များနှင့် Vĩnh Tiến ဝိုင်ဘုံ; ဝိုင်စမ်းသုံးရန် ငွေထပ်ပေးရသည်။"),
  ("Domaine de Marie (ပန်းရောင်ဘုရားကျောင်း)", "နံနက်", "Mai Anh တောင်ကုန်းရှိ ပန်းရောင်ဘုရားကျောင်းနှင့် ပန်းခြံ; ဝင်ခွင့်အခမဲ့။ မစ်ဆာအတွင်း လမ်းကို မပိတ်ပါနှင့်။"),
  ("ပွန်ဂူရ်ရေတံခွန်", "တစ်နေ့လုံး", "မှိုတက်ထားသော ကျောက်များပေါ်မှ ခုနစ်အဆင့် ရေတံခွန်; Da Lat မှ ၅၀ ကီလိုမီတာခန့်; ဂေါက်ကားဖြင့် ဆင်းရန် တစ်ကြိမ် ၁၅,၀၀၀ ဒေါင်ခန့်။"),
  ("Mê Linh ကော်ဖီခြံ", "နံနက်", "ကော်ဖီခြံတွင် လုပ်ငန်းစဉ်ကြည့်ရှုခြင်းနှင့် Weasel ကော်ဖီ ထုတ်လုပ်သော ကြောင်ခွေမြင်ရခြင်း။"),
  ("Tea Resort Prenn", "နံနက်", "Prenn ရေတံခွန်အနီးရှိ အနားယူရာ၊ အပြင်ပိုင်း လှုပ်ရှားမှုများရှိသည်; ဝန်ဆောင်မှုနှင့် အဆောက်အအုံ သုံးသပ်ချက်များ ရောနှော။"),
  ("Elephant ရေတံခွန် (Thác Voi)", "နံနက်", "Linh An ဘုရားကျောင်းဘေးရှိ ကြီးမားသော ရေတံခွန်၊ မြို့မှ ၁၇ ကီလိုမီတာခန့်; တစ်ခါတစ်ရံ ပိတ်သော်လည်း ဘုရားကျောင်းမှ မြင်ရသည်။"),
  ("Linh An ဘုရားကျောင်း", "နံနက်", "အမြင့် ၇၁ မီတာ Lady Buddha ရုပ်တုနှင့် ကြီးမားသော မေတ္တေယျ ရုပ်တုရှိသည်; ဝင်ခွင့်နှင့် ကားရပ်ခွင့် အခမဲ့။"),
  ("ဒလတ် ညဈေး", "ညနေ", "Nguyễn Thị Minh Khai လမ်းရှိ ညဈေး၊ ၁၇:၃၀ ခန့်မှ နောက်ညအထိ ဖွင့်သည်။ ကင်ထားသော ဆန်ပေါင်မုန့်ပါး၊ နွေးသော ပဲနို့ နှင့် bánh ướt lòng gà ကို စမ်းကြည့်ပါ။"),
  ("Vạn Thành ပန်းရွာ", "နံနက်", "Vạn Thành ရှိ ပန်းနှင့် ဟင်းသီးဟင်းရွက်ရွာ; သုံးသပ်ချက်အရ ဝင်ခွင့် ၁၀၀,၀၀၀ ဒေါင်ခန့် ဦးရေတစ်ယောက်လျှင်။"),
  ("Long Đỉnh လက်ဖက်ပြတိုက်", "နံနက်", "Trại Mát ရှိ လက်ဖက်ပြတိုက်၊ ထုတ်လုပ်ပုံ လေ့လာခြင်းနှင့် အရသာခံခြင်း; လက်မှတ် ၁၀၀,၀၀၀–၁၅၀,၀၀၀ ဒေါင် ပက်ကေ့ပေါ်မူတည်သည်။"),
  ("Linh Phước ဘုရားကျောင်း", "နံနက်", "ပေါ်စလင်နှင့် မှန်အစအနများဖြင့် မိုဇိတ် ပြုလုပ်ထားသော ဘုရားကျောင်း၊ ခုနစ်ထပ်ဘုရားပါသည်; ဝင်ခွင့်အခမဲ့၊ မြို့လယ်မှ ၆ ကီလိုမီတာခန့်။"),
  ("Dalat Wonderland", "နံနက်", "Tuyền Lâm ရေကန်ဘေးရှိ ဖျော်ဖြေရေးဥယျာဉ်၊ ATV၊ ဆလိုက်နှင့် သားရဲငယ်ဥယျာဉ်ရှိသည်; သုံးသပ်ချက်အရ အချို့ ပိတ်နေသည် သို့မဟုတ် ဟောင်းနေသည်။"),
  ("Cầu Đất လက်ဖက်တောင်", "နံနက်", "မြို့လယ်မှ ၁၅ ကီလိုမီတာခန့် အစိမ်းရောင် လက်ဖက်တောင်၊ နေထွက်ချိန်နှင့် တိမ်များအတွက် ကျော်ကြား။ Google Maps တွင် ၆:၀၀–၁၈:၀၀ ဟု ဖော်ပြသည်။"),
  ("Mongo Land", "နံနက်", "မွန်ဂိုလီပုံစံ ဥယျာဉ်၊ ယူတာ (တဲ)၊ သိုးနှင့် ကုလားအုတ်များ၊ ရွှေ့ကွေ့အိမ်စက်ဝိုင်း ဆလိုက်ရှည်ရှိသည်; လက်မှတ် ၁၄၀,၀၀၀ ဒေါင်ခန့် ဖျော်ရည် ၁ ခွက်ပါသည်။"),
  ("Dreamy Hill (Đồi Mộng Mơ)", "နံနက်", "ပန်းနှင့် အပင်ပုံဖော်ထားသော ဥယျာဉ်တောင်ကုန်း ၁၂ ဟက်တာခန့်; သုံးသပ်ချက်အရ အရွယ်ရောက်သူလက်မှတ် ၂၅၀,၀၀၀ ဒေါင်ခန့်။ နို‌ဝင်ဘာမှ ဇွန်အထိ အကောင်းဆုံး။"),
  ("Túi Mơ To ကော်ဖီဆိုင်", "ညနေနောက်ပိုင်း", "ဒေးစီပန်းလမ်းကြောင်းနှင့် ထိုင်ခုံရှိ တောင်ကုန်းကော်ဖီဆိုင်၊ နေဝင်ကြည့်ရန် သင့်တော်သည်; စနေ၊ တနင်္ဂနွေ လူများသည်။")])
